#ifndef CSM_JSON_H
#define CSM_JSON_H

#include <stddef.h>

enum json_kind {
	JSON_STRING,
	JSON_NUMBER,
	JSON_LITERAL,
	JSON_OBJECT,
	JSON_ARRAY
};

/* One step of the way from the root to a value: a member or an element. */
struct json_seg {
	char *key;		/* decoded member name; NULL inside an array */
	size_t index;		/* element number inside an array */
};

/*
 * A key or a value found by json_scan. start and end cover its raw bytes,
 * quotes and brackets included. path[depth - 1] names the token itself;
 * the root value has depth 0.
 */
struct json_token {
	enum json_kind kind;
	int is_key;
	size_t start, end;
	const struct json_seg *path;
	size_t depth;
};

typedef void (*json_visit)(const struct json_token *tok, void *ctx);

int json_scan(const char *text, size_t len, json_visit visit, void *ctx);
char *json_decode_string(const char *s, size_t len);
char *json_encode_string(const char *s);
char *json_top_string(const char *text, const char *key);

#endif
